sp_widget.client_script:
api.spinner = true;
api.server.get().then(function(response) {
    api.data.issues = response.data.result || [];
    api.spinner = false;
});

sp_widget.script:
(function() {
    data.result = [];
    try {
        var gr = new GlideRecord('x_1850353_employ_0_issue');
        gr.orderByDesc('sys_created_on');
        gr.setLimit(50);
        gr.query();
        while (gr.next()) {
            data.result.push({
                sys_id: gr.getUniqueValue(),
                description: gr.getDisplayValue('description'),
                priority: gr.getDisplayValue('priority'),
                employee: gr.getDisplayValue('employee'),
                status: gr.getDisplayValue('status')
            });
        }
    } catch(e) {
        gs.error('Issue Tracking widget error: ' + e.message);
    }
})();
